const fs = require("node:fs");
const lines = fs.readFileSync("input/shipments.csv","utf8").split("\n").filter(l=>l.length>0);
const header = lines[0].split(",");
const idIdx = header.indexOf("shipment_id");
const counts = new Map();
const rows = [];
lines.slice(1).forEach((line,i)=>{
  const cells = line.split(",");
  const row = i+1;
  const id = cells[idIdx];
  counts.set(id,(counts.get(id)||0)+1);
  rows.push({row,id});
});
const offending = rows.filter(r=>counts.get(r.id)>1);
console.log("total_data_rows="+rows.length);
console.log("offending_count="+offending.length);
console.log("offending_rows="+JSON.stringify(offending.map(r=>r.row)));
console.log("offending_detail="+JSON.stringify(offending));
'

